export const topics = seeds.map(buildTopic);
export const validateCurriculum = () => {
    const issues = [];
    const ids = new Set();
    const slugs = new Set();
    const sourceIds = new Set(sources.map((source) => source.id));
    if (topics.length !== 13)
        issues.push(`Expected 13 topics, received ${topics.length}`);
    for (const source of sources) {
        if (source.url) {
            try {
                new URL(source.url);
            }
            catch {
                issues.push(`Invalid source URL: ${source.id}`);
            }
        }
    }
    for (const topic of topics) {
        if (ids.has(topic.id))
            issues.push(`Duplicate topic id: ${topic.id}`);
        else
            ids.add(topic.id);
        if (slugs.has(topic.slug))
            issues.push(`Duplicate topic slug: ${topic.slug}`);
        else
            slugs.add(topic.slug);
        if (topic.orientation.objectives.length < 2 || topic.orientation.objectives.length > 4)
            issues.push(`${topic.id}: needs 2-4 objectives`);
        if (topic.misconceptions.length < 2)
            issues.push(`${topic.id}: needs two misconceptions`);
        if (topic.examples.length !== 5 || new Set(topic.examples.map((example) => example.role)).size !== 5)
            issues.push(`${topic.id}: needs five unique example roles`);
        if (topic.quiz.length < 8)
            issues.push(`${topic.id}: needs at least eight quiz questions`);
        const coverage = topic.quiz.map((question) => question.coverage);
        if (coverage.filter((item) => item === 'concept').length < 2)
            issues.push(`${topic.id}: needs two concept questions`);
        if (coverage.filter((item) => item === 'application').length < 2)
            issues.push(`${topic.id}: needs two application questions`);
        for (const required of ['diagnosis', 'misconception', 'ordering'])
            if (!coverage.includes(required))
                issues.push(`${topic.id}: missing ${required} question`);
        for (const question of topic.quiz) {
            if (!topic.orientation.objectives.some((objective) => objective.id === question.objectiveId))
                issues.push(`${question.id}: broken objective mapping`);
            if (!question.rationale.zh || !question.remediationSectionId || !question.retryPrompt.zh)
                issues.push(`${question.id}: missing rationale/remediation/retry`);
            if (question.options.length < 3 || question.options.filter((option) => option.correct).length !== 1)
                issues.push(`${question.id}: invalid options`);
            if (question.options.some((option) => !option.feedback.zh))
                issues.push(`${question.id}: missing option feedback`);
        }
        if (!/^\d{4}-\d{2}-\d{2}$/.test(topic.current.verifiedAt) || topic.current.sourceIds.length === 0)
            issues.push(`${topic.id}: current claim missing date/source`);
        for (const id of [...topic.sourceIds, ...topic.current.sourceIds])
            if (!sourceIds.has(id))
                issues.push(`${topic.id}: unknown source ${id}`);
    }
    return issues;
};
const curriculumIssues = validateCurriculum();
if (curriculumIssues.length)
    throw new Error(`Curriculum validation failed:\n${curriculumIssues.join('\n')}`);
export const topicBySlug = (slug) => topics.find((topic) => topic.slug === slug);
export const topicById = (id) => topics.find((topic) => topic.id === id);
